from dataclasses import dataclass

ZONES = {'company', 'team', 'personal'}

@dataclass(frozen=True)
class Tag:
    zone: str
    owner_id: str | None
    reason: str

FAIL_CLOSED = Tag('personal', None, 'fail_closed')   # matches no user

def tag_from_source(obj: dict, rules: dict) -> Tag:
    kind, sharing = obj.get('source_kind'), obj.get('sharing')
    rule = rules.get(kind)
    if rule is None or not isinstance(sharing, dict):
        return FAIL_CLOSED                    # unknown kind or missing field: never guess
    try:
        zone = rule(sharing)                  # pure function over source fields, no model
    except Exception:
        return FAIL_CLOSED
    if zone not in ZONES:
        return FAIL_CLOSED
    owner = sharing.get('owner_id') if zone == 'personal' else None
    if zone == 'personal' and (not owner or len(owner.encode()) > 256):
        return FAIL_CLOSED                    # personal needs a real owner from the source
    return Tag(zone, owner, f'rule:{kind}')

def narrower(a: Tag, b: Tag) -> Tag:         # two conflicting signals: the stricter wins
    rank = {'company': 0, 'team': 1, 'personal': 2}
    return a if rank[a.zone] >= rank[b.zone] else b

# example rules; field names are per app, check current docs before shipping each one
RULES = {
  'drive.file': lambda s: 'team' if s.get('drive_type') == 'shared_drive' else ('team' if s.get('shared_with') else 'personal'),
  'chat.channel': lambda s: 'company' if s.get('is_public') else 'team',
  'chat.dm': lambda s: 'personal',
}

