from dataclasses import dataclass

@dataclass(frozen=True)
class OwnerTerm:
    owner_id: str | None
    match_nothing: bool

def owner_term(ctx) -> OwnerTerm:
    if not ctx.user_id:                        # no verified user: personal branch matches nothing
        return OwnerTerm(None, True)
    return OwnerTerm(ctx.user_id, False)

PERSONAL_SQL = (
    "(c.zone <> 'personal' AND a.principals && %(principals)s) "
    "OR (c.zone = 'personal' AND c.owner_id = %(owner)s)"
)

def build_where(f, t: OwnerTerm):
    if f is None:                               # tricky part: a client with no filter must fail closed
        raise PermissionError('query without filter object')
    owner = None if t.match_nothing else t.owner_id
    return PERSONAL_SQL, {'principals': f.principals, 'owner': owner}
    # owner None makes 'owner_id = NULL' false, so the personal branch returns 0 rows

def hydrate_recheck(db, ptr_id, ctx, audit) -> bool:
    row = db.execute('SELECT zone, owner_id FROM pointer WHERE doc_id = %s', (ptr_id,)).fetchone()
    if row is None:
        return False
    zone, owner = row
    if zone == 'personal' and owner != ctx.user_id:
        audit('owner_recheck_denied', ptr_id=ptr_id)   # a hit here means a gate upstream has a bug
        return False
    return True

