RANK = {'company': 0, 'team': 1, 'personal': 2}
HUMAN_KINDS = {'owner_session'}
PROMPT_DAYS = 14

def request_promotion(db, audit, uri, to_zone, trigger, actor, observed_sharing=None):
    ptr = db.execute('SELECT zone, owner_id, zone_version FROM pointer WHERE uri=%s', (uri,)).fetchone()
    if ptr is None:
        return Decision(False, 'no_pointer')
    zone, owner, ver = ptr
    if RANK[to_zone] > RANK[zone]:                      # narrowing is always allowed
        return apply(db, audit, uri, zone, to_zone, 'narrowing', actor.id, ver)
    if trigger == 'source_sharing':
        # the widening must be visible in the fetched source object, not claimed by the caller
        if observed_sharing is None or observed_zone(observed_sharing) != to_zone:
            return Decision(False, 'source_does_not_show_it')
        return apply(db, audit, uri, zone, to_zone, trigger, 'source', ver)
    if trigger == 'owner_confirm':
        if actor.kind not in HUMAN_KINDS or actor.user_id != owner:
            return Decision(False, 'not_the_owner')     # tricky part: models and services never promote
        if not prompt_open(db, uri, owner, to_zone):
            return Decision(False, 'no_open_prompt')
        return apply(db, audit, uri, zone, to_zone, trigger, actor.user_id, ver)
    return Decision(False, 'unknown_trigger')

def apply(db, audit, uri, frm, to, trigger, actor, ver):
    audit('promotion', uri=uri, frm=frm, to=to, trigger=trigger, actor=actor)   # log first, then change
    n = db.execute('UPDATE pointer SET zone=%s, zone_version=zone_version+1 WHERE uri=%s AND zone_version=%s', (to, uri, ver)).rowcount
    return Decision(n == 1, 'applied' if n == 1 else 'lost_race')

