RANK = {'company': 0, 'team': 1, 'personal': 2}

class TaintRejected(Exception):
    pass

def rank_of(zone) -> int:
    return RANK.get(zone, 2)                  # unknown or missing label counts as personal

def taint_of(inputs):
    if not inputs:
        raise TaintRejected('no inputs listed')   # a writer must name what it used
    rank = max(rank_of(i.zone) for i in inputs)
    owners = sorted({i.owner_id for i in inputs if rank_of(i.zone) == 2 and i.owner_id})
    return Taint(rank, owners)

CEILING = {'lesson': 0, 'answer_cache_company': 0, 'answer_cache_team': 1, 'answer_cache_personal': 2}

def check_write(store, taint):
    ceiling = CEILING.get(store)
    if ceiling is None:
        raise TaintRejected(f'unknown store {store}')       # new stores must register a ceiling
    if taint.rank > ceiling:
        count_rejection(store, taint.rank)
        raise TaintRejected(f'rank {taint.rank} above ceiling {ceiling} for {store}')

def serve_ok(row_rank, row_owners, asker_id) -> bool:
    if row_rank < 2:
        return True
    # tricky part: a personal row built from two owners is served only to someone who owns all of them
    return bool(row_owners) and all(o == asker_id for o in row_owners)

