AUD = ["me", "team", "department", "company"]

def decide(db, owner, card_id, decision, audience, edits):
    card = db.draft(card_id, owner)                            # only the owner can decide
    if AUD.index(audience) > AUD.index(policy_for(owner)):
        raise PolicyError(audience)
    if decision == "approve":
        promote(card.apply(edits), audience)
    db.log_decision(card_id, owner, decision, audience, diff(card, edits))
    return Decision(decision)
